import base64
import os
from dataclasses import dataclass
from typing import Dict, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


@dataclass
class EnvelopeCiphertext:
    encrypted_data_key: str
    iv: str
    ciphertext: str
    key_id: str
    encryption_context: Optional[Dict[str, str]] = None


class KMSEnvelopeEncryptor:
    def __init__(self, key_id: Optional[str] = None, region_name: Optional[str] = None):
        self.key_id = key_id or os.environ.get("AWS_KMS_KEY_ID")
        if not self.key_id:
            raise ValueError("Missing AWS KMS key id. Set AWS_KMS_KEY_ID or pass key_id.")

        self.kms = boto3.client("kms", region_name=region_name or os.environ.get("AWS_REGION"))

    @staticmethod
    def _b64encode(data: bytes) -> str:
        return base64.b64encode(data).decode("ascii")

    @staticmethod
    def _b64decode(data: str) -> bytes:
        return base64.b64decode(data.encode("ascii"))

    def encrypt(self, plaintext: bytes, encryption_context: Optional[Dict[str, str]] = None) -> EnvelopeCiphertext:
        try:
            resp = self.kms.generate_data_key(
                KeyId=self.key_id,
                KeySpec="AES_256",
                EncryptionContext=encryption_context or {},
            )
            plaintext_data_key = resp["Plaintext"]
            encrypted_data_key = resp["CiphertextBlob"]

            iv = os.urandom(12)
            ciphertext = self._aes_gcm_encrypt(plaintext_data_key, iv, plaintext, encryption_context or {})

            return EnvelopeCiphertext(
                encrypted_data_key=self._b64encode(encrypted_data_key),
                iv=self._b64encode(iv),
                ciphertext=self._b64encode(ciphertext),
                key_id=self.key_id,
                encryption_context=encryption_context,
            )
        finally:
            if "plaintext_data_key" in locals() and plaintext_data_key is not None:
                self._zeroize(plaintext_data_key)

    def decrypt(self, envelope: EnvelopeCiphertext) -> bytes:
        encrypted_data_key = self._b64decode(envelope.encrypted_data_key)
        iv = self._b64decode(envelope.iv)
        ciphertext = self._b64decode(envelope.ciphertext)

        try:
            resp = self.kms.decrypt(
                CiphertextBlob=encrypted_data_key,
                EncryptionContext=envelope.encryption_context or {},
            )
            plaintext_data_key = resp["Plaintext"]
            return self._aes_gcm_decrypt(plaintext_data_key, iv, ciphertext, envelope.encryption_context or {})
        finally:
            if "plaintext_data_key" in locals() and plaintext_data_key is not None:
                self._zeroize(plaintext_data_key)

    @staticmethod
    def _aes_gcm_encrypt(key: bytes, iv: bytes, plaintext: bytes, aad_context: Dict[str, str]) -> bytes:
        from cryptography.hazmat.primitives.ciphers.aead import AESGCM

        aad = KMSEnvelopeEncryptor._encode_aad(aad_context)
        return AESGCM(key).encrypt(iv, plaintext, aad)

    @staticmethod
    def _aes_gcm_decrypt(key: bytes, iv: bytes, ciphertext: bytes, aad_context: Dict[str, str]) -> bytes:
        from cryptography.hazmat.primitives.ciphers.aead import AESGCM

        aad = KMSEnvelopeEncryptor._encode_aad(aad_context)
        return AESGCM(key).decrypt(iv, ciphertext, aad)

    @staticmethod
    def _encode_aad(encryption_context: Dict[str, str]) -> bytes:
        if not encryption_context:
            return b""
        items = sorted(encryption_context.items())
        return "&".join(f"{k}={v}" for k, v in items).encode("utf-8")

    @staticmethod
    def _zeroize(data: bytes) -> None:
        try:
            if isinstance(data, bytearray):
                for i in range(len(data)):
                    data[i] = 0
        except Exception:
            pass


def encrypt_bytes(plaintext: bytes, key_id: Optional[str] = None, encryption_context: Optional[Dict[str, str]] = None) -> dict:
    encryptor = KMSEnvelopeEncryptor(key_id=key_id)
    envelope = encryptor.encrypt(plaintext, encryption_context=encryption_context)
    return {
        "encrypted_data_key": envelope.encrypted_data_key,
        "iv": envelope.iv,
        "ciphertext": envelope.ciphertext,
        "key_id": envelope.key_id,
        "encryption_context": envelope.encryption_context or {},
    }


def decrypt_bytes(envelope_dict: dict, key_id: Optional[str] = None) -> bytes:
    encryptor = KMSEnvelopeEncryptor(key_id=key_id or envelope_dict.get("key_id"))
    envelope = EnvelopeCiphertext(
        encrypted_data_key=envelope_dict["encrypted_data_key"],
        iv=envelope_dict["iv"],
        ciphertext=envelope_dict["ciphertext"],
        key_id=envelope_dict.get("key_id", encryptor.key_id),
        encryption_context=envelope_dict.get("encryption_context") or {},
    )
    return encryptor.decrypt(envelope)
